  final Value<int?> receivedAtMs;
  final Value<int?> serverTimeMs;
  final Value<int?> stateVersion;
  final Value<int?> contentVersion;
  final Value<String?> client;
  final Value<String?> entitlements;
  final Value<String?> daily;
  final Value<int> comebackClaimable;
  final Value<int?> comebackClaimedAtMs;
  final Value<int?> comebackAnsweredAtMs;
  const ServerInfoCompanion({
    this.id = const Value.absent(),
    this.receivedAtMs = const Value.absent(),
    this.serverTimeMs = const Value.absent(),
    this.stateVersion = const Value.absent(),
    this.contentVersion = const Value.absent(),
    this.client = const Value.absent(),
    this.entitlements = const Value.absent(),
    this.daily = const Value.absent(),
    this.comebackClaimable = const Value.absent(),
    this.comebackClaimedAtMs = const Value.absent(),
    this.comebackAnsweredAtMs = const Value.absent(),
  });
  ServerInfoCompanion.insert({
    this.id = const Value.absent(),
    this.receivedAtMs = const Value.absent(),
    this.serverTimeMs = const Value.absent(),
    this.stateVersion = const Value.absent(),
    this.contentVersion = const Value.absent(),
    this.client = const Value.absent(),
    this.entitlements = const Value.absent(),
    this.daily = const Value.absent(),
    required int comebackClaimable,
    this.comebackClaimedAtMs = const Value.absent(),
    this.comebackAnsweredAtMs = const Value.absent(),
  }) : comebackClaimable = Value(comebackClaimable);
  static Insertable<ServerInfoData> custom({
    Expression<int>? id,
    Expression<int>? receivedAtMs,
    Expression<int>? serverTimeMs,
    Expression<int>? stateVersion,
    Expression<int>? contentVersion,
    Expression<String>? client,
    Expression<String>? entitlements,
    Expression<String>? daily,
    Expression<int>? comebackClaimable,
    Expression<int>? comebackClaimedAtMs,
    Expression<int>? comebackAnsweredAtMs,
  }) {
    return RawValuesInsertable({
      if (id != null) 'id': id,
      if (receivedAtMs != null) 'received_at_ms': receivedAtMs,
      if (serverTimeMs != null) 'server_time_ms': serverTimeMs,
      if (stateVersion != null) 'state_version': stateVersion,
      if (contentVersion != null) 'content_version': contentVersion,
      if (client != null) 'client': client,
      if (entitlements != null) 'entitlements': entitlements,
      if (daily != null) 'daily': daily,
      if (comebackClaimable != null) 'comeback_claimable': comebackClaimable,
      if (comebackClaimedAtMs != null)
        'comeback_claimed_at_ms': comebackClaimedAtMs,
      if (comebackAnsweredAtMs != null)
        'comeback_answered_at_ms': comebackAnsweredAtMs,
    });
  }

  ServerInfoCompanion copyWith({
    Value<int>? id,
    Value<int?>? receivedAtMs,
    Value<int?>? serverTimeMs,
    Value<int?>? stateVersion,
    Value<int?>? contentVersion,
    Value<String?>? client,
    Value<String?>? entitlements,
    Value<String?>? daily,
    Value<int>? comebackClaimable,
    Value<int?>? comebackClaimedAtMs,
    Value<int?>? comebackAnsweredAtMs,
  }) {
    return ServerInfoCompanion(
      id: id ?? this.id,
      receivedAtMs: receivedAtMs ?? this.receivedAtMs,
      serverTimeMs: serverTimeMs ?? this.serverTimeMs,
      stateVersion: stateVersion ?? this.stateVersion,
      contentVersion: contentVersion ?? this.contentVersion,
      client: client ?? this.client,
      entitlements: entitlements ?? this.entitlements,
      daily: daily ?? this.daily,
      comebackClaimable: comebackClaimable ?? this.comebackClaimable,
      comebackClaimedAtMs: comebackClaimedAtMs ?? this.comebackClaimedAtMs,
      comebackAnsweredAtMs: comebackAnsweredAtMs ?? this.comebackAnsweredAtMs,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (id.present) {
      map['id'] = Variable<int>(id.value);
    }
    if (receivedAtMs.present) {
      map['received_at_ms'] = Variable<int>(receivedAtMs.value);
    }
    if (serverTimeMs.present) {
      map['server_time_ms'] = Variable<int>(serverTimeMs.value);
    }
    if (stateVersion.present) {
      map['state_version'] = Variable<int>(stateVersion.value);
    }
    if (contentVersion.present) {
      map['content_version'] = Variable<int>(contentVersion.value);
    }
    if (client.present) {
      map['client'] = Variable<String>(client.value);
    }
    if (entitlements.present) {
      map['entitlements'] = Variable<String>(entitlements.value);
    }
    if (daily.present) {
      map['daily'] = Variable<String>(daily.value);
    }
    if (comebackClaimable.present) {
      map['comeback_claimable'] = Variable<int>(comebackClaimable.value);
    }
    if (comebackClaimedAtMs.present) {
      map['comeback_claimed_at_ms'] = Variable<int>(comebackClaimedAtMs.value);
    }
    if (comebackAnsweredAtMs.present) {
      map['comeback_answered_at_ms'] = Variable<int>(
        comebackAnsweredAtMs.value,
      );
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('ServerInfoCompanion(')
          ..write('id: $id, ')
          ..write('receivedAtMs: $receivedAtMs, ')
          ..write('serverTimeMs: $serverTimeMs, ')
          ..write('stateVersion: $stateVersion, ')
          ..write('contentVersion: $contentVersion, ')
          ..write('client: $client, ')
          ..write('entitlements: $entitlements, ')
          ..write('daily: $daily, ')
          ..write('comebackClaimable: $comebackClaimable, ')
          ..write('comebackClaimedAtMs: $comebackClaimedAtMs, ')
          ..write('comebackAnsweredAtMs: $comebackAnsweredAtMs')
          ..write(')'))
        .toString();
  }
}

class DatabaseAtV3 extends GeneratedDatabase {
