  late final Wallet wallet = Wallet(this);
  late final Inventory inventory = Inventory(this);
  late final Ownership ownership = Ownership(this);
  late final TripProgress tripProgress = TripProgress(this);
  late final TripSession tripSession = TripSession(this);
  late final ProjectionBase projectionBase = ProjectionBase(this);
  late final ClockAnchor clockAnchor = ClockAnchor(this);
  late final TripRecord tripRecord = TripRecord(this);
  late final TripRecordCommand tripRecordCommand = TripRecordCommand(this);
  late final TripIntent tripIntent = TripIntent(this);
  late final Account account = Account(this);
  late final ServerInfo serverInfo = ServerInfo(this);
  late final Index ledgerOpsSync = Index(
    'ledger_ops_sync',
    'CREATE INDEX ledger_ops_sync ON ledger_ops (sync_status, seq)',
  );
  late final Index ledgerOpsRef = Index(
    'ledger_ops_ref',
    'CREATE INDEX ledger_ops_ref ON ledger_ops (ref)',
  );
  @override
  Iterable<TableInfo<Table, Object?>> get allTables =>
      allSchemaEntities.whereType<TableInfo<Table, Object?>>();
  @override
  List<DatabaseSchemaEntity> get allSchemaEntities => [
    ledgerOps,
    wallet,
    inventory,
    ownership,
    tripProgress,
    tripSession,
    projectionBase,
    clockAnchor,
    tripRecord,
    tripRecordCommand,
    tripIntent,
    account,
    serverInfo,
    ledgerOpsSync,
    ledgerOpsRef,
  ];
  @override
  int get schemaVersion => 3;
}
